<script setup lang="ts">
import { useRoute } from 'vue-router';
import { useStore } from 'vuex';
import { computed, onMounted, ref } from 'vue';
import { Heading } from '@/shared/ui/text/heading'
import { Text } from '@/shared/ui/text/paragraph';

const route = useRoute()
const store = useStore();
const loading = ref(true);

const projectSlug = computed(() => String(route.params.slug));

const project = computed(() => {
    return store.getters['projects/getProjectsBySlug'](projectSlug.value);
});

onMounted(async () => {
    if (store.state.projects.projectsData.length === 0) {
        await store.dispatch('projects/fetchProjects');
    }
    loading.value = false;
});

interface ContentParagraph {
    text: string;
    isHeading: boolean;
}

const isHeading = (text: string): boolean => {
    const headingPatterns = [
        /мероприятие:/i,
        /задача:/i,
        /решение:/i,
        /результат:/i,
        /^[А-Я][а-я]+:/
    ];

    return headingPatterns.some(pattern => pattern.test(text));
};

const formatText = (text: string): string => {
    if (isHeading(text)) {
        return text.replace(':', '').trim();
    }
    return text.trim();
};

const contentParagraphs = computed((): ContentParagraph[] => {
    if (!project.value?.text) return [];

    return project.value.text
        .split('\n')
        .filter((line: string) => line.trim())
        .map((line: string) => ({
            text: formatText(line),
            isHeading: isHeading(line)
        }));
});
</script>

<template>
    <div v-if="loading">Загрузка...</div>
    <div v-else-if="project" class="project-content">
        <Heading tagName="h1" color="dark" size="m">
            {{ project.title }}
        </Heading>

        <div class="content-paragraphs">
            <div v-for="(paragraph, index) in contentParagraphs" :key="index" class="paragraph">
                <Text tagName="p" size="l" color="dark-gray2" v-if="paragraph.isHeading">
                    {{ paragraph.text }}
                </Text>
                <Text tagName="p" size="l" color="dark-gray2" v-else>
                    {{ paragraph.text }}
                </Text>
            </div>
        </div>
    </div>
   
</template>

<style scoped lang="scss">
h1 {
  margin: 10px 0 30px;
}</style>